pub struct Parsed {
    pub term: Term,
    pub variables: Vec<Variable>,
    pub next: usize
}
pub fn symbol(c: u8) -> bool {
    b"+-*/\\^<>=~:.?@#&$".contains(&c)
}
pub fn infix(name: &str) -> Option<(usize, usize, usize)> {
    let (p, kind) = match name {
        ":-" => (1200, "xfx"),
        ";" => (1100, "xfy"),
        "->" => (1050, "xfy"),
        "," => (1000, "xfy"),
        "=" | "\\=" | "==" | "\\==" | "is" | "=:=" | "=\\=" | "<" | ">" | "=<" | ">=" | "=.." => (700, "xfx"),
        "+" | "-" => (500, "yfx"),
        "*" | "/" | "//" | "mod" | "rem" => (400, "yfx"),
        _ => return None
    };
    Some((p, if kind == "yfx" {
        p
    } else {
        p - 1
    }, if kind == "xfy" {
        p
    } else {
        p - 1
    }))
}
pub fn prefix(name: &str) -> Option<usize> {
    match name {
        "\\+" => Some(900),
        "-" => Some(200),
        _ => None
    }
}
pub fn operator(name: &str) -> bool {
    infix(name).is_some() || prefix(name).is_some()
}
pub fn lex(text: &str, first_column: usize) -> Vec<Token> {
    let bytes = text.as_bytes();
    let mut tokens = Vec::new();
    let mut i = 0;
    let mut line = 1;
    let mut column = first_column;
    let mut space = true;
    while i < bytes.len() {
        if bytes[i] == b' ' {
            i += 1;
            column += 1;
            space = true;
            continue;
        }
        if bytes[i] == b'\n' {
            i += 1;
            line += 1;
            column = 1;
            space = true;
            continue;
        }
        if bytes[i] == b'%' {
            while i < bytes.len() && bytes[i] != b'\n' {
                i += 1;
                column += 1;
            }
            space = true;
            continue;
        }
        let start = i;
        let at = column;
        let kind;
        let mut name = String::new();
        if bytes[i].is_ascii_digit() {
            i += 1;
            while i < bytes.len() && bytes[i].is_ascii_digit() {
                i += 1;
            }
            if text[start..i].parse::<i64>().ok().map_or(true, |n| n > 2147483647) {
                kind = "invalid";
                name = "integer too large".into();
            } else {
                kind = "integer";
            }
        }
        else if bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' {
            i += 1;
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') {
                i += 1;
            }
            kind = if bytes[start].is_ascii_lowercase() {
                "name"
            } else {
                "variable"
            };
        }
        else if symbol(bytes[i]) {
            i += 1;
            while i < bytes.len() && symbol(bytes[i]) {
                i += 1;
            }
            kind = if &text[start..i] == "." && (i == bytes.len() || b" \n%".contains(&bytes[i])) {
                "end"
            } else {
                "name"
            };
        }
        else if bytes[i] == b'!' || bytes[i] == b';' {
            i += 1;
            kind = "name";
        }
        else if b",|()[]".contains(&bytes[i]) {
            i += 1;
            kind = "punctuation";
        }
        else if bytes[i] == b'\'' {
            i += 1;
            let mut invalid = false;
            let mut closed = false;
            while i < bytes.len() && bytes[i] != b'\n' {
                if bytes[i] == b'\'' {
                    if bytes.get(i + 1) == Some(&b'\'') {
                        name.push('\'');
                        i += 2;
                    } else {
                        i += 1;
                        closed = true;
                        break;
                    }
                }
                else if bytes[i] == b'\\' {
                    i += 1;
                    if i < bytes.len() && bytes[i] != b'\n' {
                        match bytes[i] {
                            b'n' => name.push('\n'),
                            b't' => name.push('\t'),
                            b'\\' => name.push('\\'),
                            b'\'' => name.push('\''),
                            _ => invalid = true
                        }
                        i += 1;
                    }
                } else {
                    name.push(bytes[i] as char);
                    i += 1;
                }
            }
            if !closed {
                kind = "invalid";
                name = "unterminated quoted atom".into();
            } else if invalid {
                kind = "invalid";
                name = "undefined escape sequence".into();
            } else {
                kind = "quoted";
            }
        } else {
            i += 1;
            kind = "invalid";
            name = format!("illegal character '{}'", bytes[start] as char);
        }
        let spelling = text[start..i].to_string();
        if name.is_empty() && kind != "quoted" {
            name = spelling.clone();
        }
        tokens.push(Token {
            kind,
            spelling,
            name,
            line,
            column: at,
            space
        });
        column += i - start;
        space = false;
    }
    tokens.push(Token {
        kind: "eof",
        spelling: String::new(),
        name: String::new(),
        line,
        column,
        space
    });
    tokens
}
struct Parser<'a> {
    tokens: &'a [Token],
    index: usize,
    store: &'a mut Store,
    variables: Vec<Variable>,
    names: BTreeMap<String,
    usize>
}
impl<'a> Parser<'a> {
    fn error(&self, index: usize) -> Error {
        let token = &self.tokens[index];
        let message = match token.kind {
            "invalid" => token.name.clone(),
            "eof" => "unexpected end of file".into(),
            "end" => "unexpected end of clause".into(),
            "name" if infix(&token.name).is_some() => "operator priority clash".into(),
            _ => format!("unexpected \"{}\"", token.spelling)
        };
        Error {
            line: token.line,
            column: token.column,
            message,
            index,
            eof: token.kind == "eof"
        }
    }
    fn peek(&self) -> &Token {
        &self.tokens[self.index]
    }
    fn take(&mut self) -> (usize, Token) {
        let index = self.index;
        let token = self.peek().clone();
        if token.kind != "eof" {
            self.index += 1;
        }
        (index, token)
    }
    fn expect(&mut self, text: &str) -> Result<(),
    Error> {
        let (i, token) = self.take();
        if token.kind == "punctuation" && token.name == text {
            Ok(())
        } else {
            Err(self.error(i))
        }
    }
    fn term(&mut self, limit: usize) -> Result<(Term, usize),
    Error> {
        let (mut term, mut priority) = self.primary(limit)?;
        loop {
            let token = self.peek();
            if token.kind != "name" && !(token.kind == "punctuation" && token.name == ",") {
                break;
            }
            let (p, left, right) = match infix(&token.name) {
                Some(operator) => operator,
                None => break
            };
            if p > limit || priority > left {
                break;
            }
            let name = self.take().1.name;
            let argument = self.term(right)?.0;
            term = Term::compound(&name, vec![term, argument]);
            priority = p;
        }
        Ok((term, priority))
    }
    fn starts(token: &Token) -> bool {
        ["integer", "variable", "quoted"].contains(&token.kind) || (token.kind == "punctuation" && (token.name == "(" || token.name == "[")) || (token.kind == "name" && (infix(&token.name).is_none() || prefix(&token.name).is_some()))
    }
    fn primary(&mut self, limit: usize) -> Result<(Term, usize),
    Error> {
        let (index, token) = self.take();
        match token.kind {
            "integer" => Ok((Term::Integer(token.name.parse().unwrap()), 0)),
            "variable" => {
                if token.name == "_" {
                    return Ok((self.store.fresh(), 0));
                }
                let variable = if let Some(&i) = self.names.get(&token.name) {
                    self.variables[i].count += 1;
                    self.variables[i].term.clone()
                } else {
                    let term = self.store.fresh();
                    self.names.insert(token.name.clone(), self.variables.len());
                    self.variables.push(Variable {
                        name: token.name,
                        term: term.clone(),
                        count: 1
                    });
                    term
                };
                Ok((variable, 0))
            },
            "punctuation" if token.name == "(" => {
                let term = self.term(1200)?.0;
                self.expect(")")?;
                Ok((term, 0))
            },
            "punctuation" if token.name == "[" => {
                if self.peek().kind == "punctuation" && self.peek().name == "]" {
                    self.take();
                    return Ok((Term::atom("[]"), 0));
                }
                let mut elements = vec![self.term(999)?.0];
                while self.peek().kind == "punctuation" && self.peek().name == "," {
                    self.take();
                    elements.push(self.term(999)?.0);
                }
                let tail = if self.peek().kind == "punctuation" && self.peek().name == "|" {
                    self.take();
                    self.term(999)?.0
                } else {
                    Term::atom("[]")
                };
                self.expect("]")?;
                Ok((list(elements, tail), 0))
            },
            "name" | "quoted" => {
                if self.peek().kind == "punctuation" && self.peek().name == "(" && !self.peek().space {
                    self.take();
                    let mut arguments = vec![self.term(999)?.0];
                    while self.peek().kind == "punctuation" && self.peek().name == "," {
                        self.take();
                        arguments.push(self.term(999)?.0);
                    }
                    self.expect(")")?;
                    return Ok((Term::compound(&token.name, arguments), 0));
                }
                if token.kind == "name" && token.name == "-" && self.peek().kind == "integer" && !self.peek().space {
                    let integer = self.take().1.name.parse::<i64>().unwrap();
                    return Ok((Term::Integer(-integer), 0));
                }
                if token.kind == "name" && prefix(&token.name).is_some() && Self::starts(self.peek()) {
                    let priority = prefix(&token.name).unwrap();
                    if priority > limit {
                        let mut error = self.error(index);
                        error.message = "operator priority clash".into();
                        return Err(error);
                    }
                    let argument = self.term(priority)?.0;
                    return Ok((Term::compound(&token.name, vec![argument]), priority));
                }
                Ok((Term::Atom(token.name), 0))
            },
            _ => Err(self.error(index))
        }
    }
}
pub fn clause(tokens: &[Token], start: usize, store: &mut Store, query: bool) -> Result<Parsed, Error> {
    let mut parser = Parser {
        tokens,
        index: start,
        store,
        variables: Vec::new(),
        names: BTreeMap::new()
    };
    let term = parser.term(1200)?.0;
    let (index, token) = parser.take();
    if token.kind != "end" {
        return Err(parser.error(index));
    }
    if query && parser.peek().kind != "eof" {
        return Err(parser.error(parser.index));
    }
    Ok(Parsed {
        term,
        variables: parser.variables,
        next: parser.index
    })
}

use std::collections::BTreeMap;
#[derive(Clone, Debug)]
pub enum Term {
    Integer(i64),
    Atom(String),
    Variable(usize),
    Compound(String, Vec<Term>)
}
pub type Indicator = (String, usize);
impl Term {
    pub fn atom(name: &str) -> Self {
        Self::Atom(name.into())
    }
    pub fn compound(name: &str, arguments: Vec<Term>) -> Self {
        Self::Compound(name.into(), arguments)
    }
    pub fn indicator(&self) -> Option<Indicator> {
        match self {
            Self::Atom(name) => Some((name.clone(), 0)),
            Self::Compound(name, arguments) => Some((name.clone(), arguments.len())),
            _ => None
        }
    }
    pub fn arguments(&self) -> Vec<Term> {
        if let Self::Compound(_, arguments) = self {
            arguments.clone()
        } else {
            Vec::new()
        }
    }
}
#[derive(Clone)]
pub struct Store {
    pub bindings: Vec<Option<Term>>
}
impl Store {
    pub fn new() -> Self {
        Self {
            bindings: Vec::new()
        }
    }
    pub fn fresh(&mut self) -> Term {
        let id = self.bindings.len();
        self.bindings.push(None);
        Term::Variable(id)
    }
    pub fn dereference(&self, term: &Term) -> Term {
        let mut term = term.clone();
        while let Term::Variable(id) = term {
            if let Some(value) = &self.bindings[id] {
                term = value.clone();
            } else {
                break;
            }
        }
        term
    }
    pub fn copy(&mut self, term: &Term) -> Term {
        self.copy_with(term, &mut BTreeMap::new())
    }
    fn copy_with(&mut self, term: &Term, variables: &mut BTreeMap<usize, Term>) -> Term {
        match self.dereference(term) {
            Term::Variable(id) => {
                if let Some(value) = variables.get(&id) {
                    value.clone()
                } else {
                    let fresh = self.fresh();
                    variables.insert(id, fresh.clone());
                    fresh
                }
            },
            Term::Compound(name, arguments) => Term::Compound(name, arguments.iter().map(|a| self.copy_with(a, variables)).collect()),
            term => term
        }
    }
    pub fn copy_many(&mut self, terms: &[Term]) -> Vec<Term> {
        let mut variables = BTreeMap::new();
        terms.iter().map(|t| self.copy_with(t, &mut variables)).collect()
    }
    pub fn parts(&self, term: &Term) -> (Vec<Term>, Term) {
        let mut term = self.dereference(term);
        let mut elements = Vec::new();
        loop {
            match term {
                Term::Compound(ref name, ref arguments) if name == "." && arguments.len() == 2 => {
                    elements.push(arguments[0].clone());
                    term = self.dereference(&arguments[1]);
                },
                _ => return (elements, term)
            }
        }
    }
    pub fn variables(&self, terms: &[Term]) -> Vec<usize> {
        let mut pending: Vec<Term> = terms.iter().rev().cloned().collect();
        let mut variables = Vec::new();
        while let Some(term) = pending.pop() {
            match self.dereference(&term) {
                Term::Variable(id) => variables.push(id),
                Term::Compound(_, arguments) => pending.extend(arguments.into_iter().rev()),
                _ => ()
            }
        }
        variables
    }
}
pub fn list(elements: Vec<Term>, tail: Term) -> Term {
    elements.into_iter().rev().fold(tail, |tail, element| Term::compound(".", vec![element, tail]))
}
pub fn indicator_term(indicator: &Indicator) -> Term {
    Term::compound("/", vec![Term::Atom(indicator.0.clone()), Term::Integer(indicator.1 as i64)])
}
pub fn type_error(kind: &str, term: Term) -> Term {
    Term::compound("type_error", vec![Term::atom(kind), term])
}
pub fn domain_error(kind: &str, term: Term) -> Term {
    Term::compound("domain_error", vec![Term::atom(kind), term])
}
pub fn error_ball(error: Term, indicator: &Indicator) -> Term {
    Term::compound("error", vec![error, indicator_term(indicator)])
}
pub fn same_kind(a: &Term, b: &Term, store: &Store) -> bool {
    match (store.dereference(a), store.dereference(b)) {
        (Term::Variable(_), _) | (_, Term::Variable(_)) => true,
        (Term::Integer(a), Term::Integer(b)) => a == b,
        (Term::Atom(a), Term::Atom(b)) => a == b,
        (Term::Compound(a, aa), Term::Compound(b, ba)) => a == b && aa.len() == ba.len(),
        _ => false
    }
}

use crate::terms::{
    Term,
    Store
};
pub struct Trail {
    bindings: Vec<usize>
}
impl Trail {
    pub fn new() -> Self {
        Self {
            bindings: Vec::new()
        }
    }
    pub fn mark(&self) -> usize {
        self.bindings.len()
    }
    pub fn undo(&mut self, mark: usize, store: &mut Store) {
        while self.bindings.len() > mark {
            let id = self.bindings.pop().unwrap();
            store.bindings[id] = None;
        }
    }
    pub fn unify(&mut self, a: &Term, b: &Term, store: &mut Store) -> bool {
        let mut pending = vec![(a.clone(), b.clone())];
        while let Some((a, b)) = pending.pop() {
            let a = store.dereference(&a);
            let b = store.dereference(&b);
            match (a, b) {
                (Term::Variable(a), Term::Variable(b)) if a == b => (),
                (Term::Variable(id), term) | (term, Term::Variable(id)) => {
                    store.bindings[id] = Some(term);
                    self.bindings.push(id);
                },
                (Term::Integer(a), Term::Integer(b)) if a == b => (),
                (Term::Atom(a), Term::Atom(b)) if a == b => (),
                (Term::Compound(a, aa), Term::Compound(b, ba)) if a == b && aa.len() == ba.len() => pending.extend(aa.into_iter().zip(ba).rev()),
                _ => return false
            }
        }
        true
    }
}
pub fn identical(a: &Term, b: &Term, store: &Store) -> bool {
    let mut pending = vec![(a.clone(), b.clone())];
    while let Some((a, b)) = pending.pop() {
        match (store.dereference(&a), store.dereference(&b)) {
            (Term::Variable(a), Term::Variable(b)) if a == b => (),
            (Term::Integer(a), Term::Integer(b)) if a == b => (),
            (Term::Atom(a), Term::Atom(b)) if a == b => (),
            (Term::Compound(a, aa), Term::Compound(b, ba)) if a == b && aa.len() == ba.len() => pending.extend(aa.into_iter().zip(ba).rev()),
            _ => return false
        }
    }
    true
}
